abstract interface class _Json {
  Object? toJson();
}

T _as<T>(Object? v) => v as T;

T Function(Object?) _obj<T>(T Function(Map<String, Object?>) f) {
  return (v) => f(v as Map<String, Object?>);
}

T? _opt<T>(Object? v, T Function(Object?) f) => v == null ? null : f(v);

List<T> _list<T>(Object? v, T Function(Object?) f) {
  return (v as List<Object?>).map(f).toList();
}

List<T>? _listOrNull<T>(Object? v, T Function(Object?) f) {
  return v == null ? null : _list(v, f);
}

Map<String, T> _map<T>(Object? v, T Function(Object?) f) {
  return (v as Map<String, Object?>).map((k, e) => MapEntry(k, f(e)));
}

Map<String, T>? _mapOrNull<T>(Object? v, T Function(Object?) f) {
  return v == null ? null : _map(v, f);
}

List<Object?>? _jsonList(List<_Json>? xs) {
  return xs?.map((x) => x.toJson()).toList();
}

Never _unsendable(String type) {
  throw StateError('$type.\$unknown cannot be sent');
}
